import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { OrbitControls } from '@react-three/drei';
import { OBJLoader } from 'three/examples/jsm/loaders/OBJLoader';
import * as THREE from 'three';
import './App.css';

// Add to your CSS file
`
.model-container {
  position: relative;
  width: 100%;
  height: 100%;
}

.model-layer {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  transition: opacity 0.5s ease-in-out;
}

.model-layer.active {
  opacity: 1;
}
`

const useModelCache = () => {
  const [modelCache, setModelCache] = useState({});
  const [loadingModels, setLoadingModels] = useState({});

  const loadModel = useCallback((modelPath) => {
    return new Promise((resolve, reject) => {
      // Check if model is already cached
      if (modelCache[modelPath]) {
        resolve(modelCache[modelPath]);
        return;
      }

      // Check if model is currently loading
      if (loadingModels[modelPath]) {
        loadingModels[modelPath].then(resolve);
        return;
      }

      const loader = new OBJLoader();
      const modelLoading = new Promise((innerResolve, innerReject) => {
        loader.load(
          modelPath,
          (obj) => {
            const newModelRef = new THREE.Group();

            const box = new THREE.Box3().setFromObject(obj);
            const size = box.getSize(new THREE.Vector3());
            const maxDimension = Math.max(size.x, size.y, size.z);
            obj.rotation.x = -Math.PI / 2;
            const scaleFactor = 2.5 / maxDimension;
            obj.scale.set(scaleFactor, scaleFactor, scaleFactor);

            box.setFromObject(obj);
            const center = box.getCenter(new THREE.Vector3());
            obj.position.sub(center);

            obj.traverse((child) => {
              if (child.isMesh) {
                const edges = new THREE.EdgesGeometry(child.geometry, 45);
                const lineMaterial = new THREE.LineBasicMaterial({
                  color: 0xffffff,
                  opacity: 0.5,
                  transparent: true,
                });
                const edgeLines = new THREE.LineSegments(edges, lineMaterial);
                edgeLines.position.copy(child.position);
                edgeLines.rotation.copy(child.rotation);
                edgeLines.scale.copy(child.scale);
                child.parent.add(edgeLines);
                child.parent.remove(child);
              }
            });

            newModelRef.add(obj);

            // Update cache
            setModelCache(prev => ({
              ...prev,
              [modelPath]: newModelRef
            }));

            // Remove from loading models
            setLoadingModels(prev => {
              const updated = {...prev};
              delete updated[modelPath];
              return updated;
            });

            innerResolve(newModelRef);
            resolve(newModelRef);
          },
          undefined,
          (error) => {
            innerReject(error);
            reject(error);
          }
        );
      });

      // Track loading models
      setLoadingModels(prev => ({
        ...prev,
        [modelPath]: modelLoading
      }));

      return modelLoading;
    });
  }, [modelCache]);

  return { modelCache, loadModel };
};

const ModelLayer = ({ modelPath, isActive, onRotate }) => {
  const [model, setModel] = useState(null);
  const { loadModel } = useModelCache();
  const groupRef = useRef(null);

  useEffect(() => {
    loadModel(modelPath)
      .then(setModel)
      .catch(error => console.error('Error loading OBJ:', error));
  }, [modelPath, loadModel]);

  // Apply rotations to the model group
  useFrame(() => {
    if (groupRef.current) {
      groupRef.current.rotation.y += 0.003;
      onRotate?.(groupRef.current);
    }
  });

  return (
    <group ref={groupRef} className={`model-layer ${isActive ? 'active' : ''}`}>
      {!model && (
        <mesh>
          <boxGeometry args={[1, 1, 1]} />
          <meshBasicMaterial color="white" wireframe={true} />
        </mesh>
      )}
      {model && <primitive object={model} />}
    </group>
  );
};

const App = () => {
  const [models, setModels] = useState([]);
  const [selectedModel, setSelectedModel] = useState(null);
  const [highlightedModel, setHighlightedModel] = useState(null);
  const [asciiArt, setAsciiArt] = useState('');
  const [asciiIndex, setAsciiIndex] = useState(0);
  const [asciiComplete, setAsciiComplete] = useState(false);
  const [activeModels, setActiveModels] = useState([]);
  const { modelCache, loadModel } = useModelCache();

  useEffect(() => {
    fetch('./models.json')
      .then((response) => response.json())
      .then((data) => {
        setModels(data);
        const firstModel = data[0]?.file;
        setSelectedModel(firstModel);

        // Preload all models in the background
        data.forEach(model => {
          loadModel(`./stls/${model.file}`);
        });
      })
      .catch((error) => console.error('Error loading models:', error));
  }, []);

  // Manage active models for fade effect
  useEffect(() => {
    if (selectedModel) {
      setActiveModels(prev => {
        // Remove the oldest model if we have more than 2
        const updated = [...prev, selectedModel].slice(-2);
        return updated;
      });
    }
  }, [selectedModel]);

  const asciiArtString = `
......................................................................................................
..............@@@@......................@@@....................@@@@...................................
.............@@..@@...................@@@@@@@.................@@@@@@@..........@@@@@@@@@@@@@@@@@@@@...
............@@....@@.................@@@@@@@@@..............@@@@@@@@@@.........@@@@@@@@@@@@@@@@@@@....
............@......@...............@@@@@@@@@@@@@...........@@@@@@@@@@@@........@@@@@@@@@@@@@@@@@......
...........@@......@@.............@@@@@@@@@@@@@@@.........@@@@@@@@@@@@@@@......@@@@@@@@@@@@@@@@.......
..........@@........@@.............@@@@@@@@@@@@@..........@@@@@@@@@@@@@@.................@@@@.........
.........@@..........@@.............@@@@@@@@@@@.............@@@@@@@@@@@..................@@@..........
........@@...........@@..............@@@@@@@@................@@@@@@@@....................@@...........
.......@@.............@@.............@@@@@@@@................@@@@@@@@....................@............
.......@@.....@@@@.....@@...........@@@.@@..@@..............@@@.@@.@@@.........@@@@@..................
......@@......@..@......@@.........@@@......@@@...........@@@@......@@@........@@@@@..................
.....@@......@....@@@@@@@@........@@@...@@@..@@@@.........@@@..@@@...@@@........@@@@@.................
....@@......@.@@@@@@@@@@@@@......@@@...@@@@@..@@@........@@@...@@@@...@@@.......@@@@@@@...............
....@......@@.@@@.........@@....@@@....@@@@@...@@@......@@@...@@@@@@...@@@.......@@@@@@@@@@@@@@@@.....
..@@@.....@@....@@@........@@..@@@@@@@@@@@@@@@@@@@@....@@@@@@@@@@@@@@@@@@@@........@@@@@@@@@@@@@@.....
..@@@@@@@@@........@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@..@@@@@@@@@@@@@@@@@@@@@@.........@@@@@@@@@@@@.....
......................................................................................................
  `;

  useEffect(() => {
    if (asciiIndex < asciiArtString.length) {
      const interval = setInterval(() => {
        setAsciiArt((prev) => prev + asciiArtString[asciiIndex]);
        setAsciiIndex((prev) => prev + 1);
      }, 5);

      return () => clearInterval(interval);
    } else {
      setAsciiComplete(true);
    }
  }, [asciiIndex, asciiArtString]);

  const handleKeyPress = useCallback((event) => {
    const currentIndex = models.findIndex((model) => model.file === selectedModel);
    if (event.key === 'ArrowDown') {
      const nextIndex = (currentIndex + 1) % models.length;
      setSelectedModel(models[nextIndex]?.file);
    } else if (event.key === 'ArrowUp') {
      const prevIndex = (currentIndex - 1 + models.length) % models.length;
      setSelectedModel(models[prevIndex]?.file);
    }
  }, [models, selectedModel]);

  useEffect(() => {
    window.addEventListener('keydown', handleKeyPress);
    return () => {
      window.removeEventListener('keydown', handleKeyPress);
    };
  }, [handleKeyPress]);

  const handleModelClick = (model) => {
    setSelectedModel(model.file);
  };

  return (
    <div className="container">
      <div className="sidebar">
        <h3>Select a Project</h3>
        <ul>
          {models.map((model) => (
            <li
              key={model.file}
              className={`${selectedModel === model.file ? 'selected' : ''} ${highlightedModel === model.file ? 'highlighted' : ''}`}
              onClick={() => handleModelClick(model)}
              onMouseEnter={() => setHighlightedModel(model.file)}
              onMouseLeave={() => setHighlightedModel(null)}
            >
              {selectedModel === model.file ? `> ${model.name}` : model.name}
            </li>
          ))}
        </ul>
      </div>

      <div className="right-container">
        {!asciiComplete && (
          <div className="ascii-art">
            {asciiArt}
          </div>
        )}

        {asciiComplete && (
          <Canvas
            style={{ backgroundColor: 'black' }}
            camera={{
              position: [2.5, 2.5, 2.5],
              fov: 45,
            }}
            className="model-container"
          >
            <ambientLight intensity={0.5} />
            <spotLight position={[10, 10, 10]} intensity={1} />
            <directionalLight position={[5, 5, 5]} intensity={1} />

            {activeModels.map((modelFile, index) => (
              <ModelLayer 
                key={modelFile}
                modelPath={`./stls/${modelFile}`}
                isActive={modelFile === selectedModel}
              />
            ))}

            <OrbitControls
              enableZoom={false}
              minPolarAngle={Math.PI / 4}
              maxPolarAngle={Math.PI / 4}
              minAzimuthAngle={-Math.PI / 4}
              maxAzimuthAngle={Math.PI / 4}
            />
          </Canvas>
        )}
      </div>
    </div>
  );
};

export default App;
